'use strict';
const {LESSONS,QUESTIONS,SOURCES,TEC_INDEX,PROGRAM}=window.TRILHA;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='trilha-ti-v1';
const emptyState=()=>({version:1,completed:[],attempts:[],notes:{},days:{},tec:[]});
let state=emptyState(),storageOK=true;
try{const raw=localStorage.getItem(key);if(raw)state=validate(JSON.parse(raw));}catch(e){storageOK=false;}
function validate(v){
 if(!v||v.version!==1||!Array.isArray(v.completed)||!Array.isArray(v.attempts)||typeof v.notes!=='object'||!v.notes||typeof v.days!=='object'||!v.days||!Array.isArray(v.tec))throw Error('Formato de backup inválido.');
 if(v.attempts.length>50000||v.tec.length>10000)throw Error('Backup acima do limite desta versão.');
 const out=emptyState();out.completed=[...new Set(v.completed.filter(x=>LESSONS.some(l=>l.id===x)))];
 out.attempts=v.attempts.map(a=>{const q=QUESTIONS.find(q=>q.id===a.id);if(!q||!Number.isInteger(a.selected)||a.selected<0||a.selected>4||!Number.isFinite(a.time)||a.time<0||a.time>Date.now()+86400000||typeof a.guess!=='boolean')throw Error('Tentativa inválida.');return {id:a.id,selected:a.selected,correct:a.selected===q.correct,time:a.time,guess:a.guess};});
 for(const q of QUESTIONS)if(typeof v.notes[q.id]==='string')out.notes[q.id]=v.notes[q.id].slice(0,5000);
 for(const [k,d] of Object.entries(v.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!d||!Array.isArray(d.checks)||!LESSONS.some(l=>l.id===d.lesson))continue;out.days[k]={lesson:d.lesson,checks:[...new Set(d.checks.filter(x=>Number.isInteger(x)&&x>=0&&x<5))]};}
 out.tec=v.tec.map(x=>{if(typeof x.topic!=='string'||!Number.isInteger(x.total)||x.total<1||x.total>1000||!Number.isInteger(x.correct)||x.correct<0||x.correct>x.total||!Number.isFinite(x.time)||x.time<0||x.time>Date.now()+86400000)throw Error('Registro TEC inválido.');return{topic:x.topic.slice(0,160),total:x.total,correct:x.correct,time:x.time};});
 return out;
}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch(e){storageOK=false;toast('Não foi possível salvar. Exporte seu progresso antes de fechar.');return false;}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4200);}
function dateKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function day(){const k=dateKey();if(!state.days[k]){state.days[k]={lesson:(LESSONS.find(l=>!state.completed.includes(l.id))||LESSONS[0]).id,checks:[]};save();}return state.days[k];}
function last(id){return [...state.attempts].reverse().find(a=>a.id===id);}
function due(){return QUESTIONS.filter(q=>{const a=last(q.id);if(!a)return false;const delay=(!a.correct||a.guess)?1:7;return a.time+delay*86400000<=Date.now();});}
const nav=(url)=>{if(location.hash.slice(1)===url)render();else location.hash=url;};
function head(eyebrow,title,subtitle,tag=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
const sourceLink=k=>{const s=SOURCES[k];return `<a href="${esc(s[1])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a>`;};
function stats(){const ids=new Set(state.attempts.map(a=>a.id)),ac=[...ids].filter(id=>last(id).correct&&!last(id).guess).length;return `<div class="stats"><div class="stat"><small>Aulas introdutórias concluídas</small><strong>${state.completed.length}<span class="subtle"> / ${LESSONS.length}</span></strong><span class="hint">Fundamentos para o primeiro ciclo</span></div><div class="stat"><small>Questões autorais praticadas</small><strong>${ids.size}<span class="subtle"> / ${QUESTIONS.length}</span></strong><span class="hint">Questões únicas, sem contar repetições</span></div><div class="stat"><small>Acertos sem palpite · última resposta</small><strong>${ids.size?Math.round(ac/ids.size*100)+'%':'—'}</strong><span class="hint">${ac} de ${ids.size} · amostra inicial</span></div><div class="stat"><small>Revisões para hoje</small><strong>${due().length}</strong><span class="hint">Erros e palpites voltam antes</span></div></div>`;}
const DAILY=[['Recordar','Recupere de memória o que já estudou.',10],['Aprender','Leia uma aula, desenhe exemplos e faça a atividade.',40],['Praticar','Resolva e explique alternativas com calma.',35],['Corrigir','Registre o motivo do erro e confira a fonte.',25],['Preparar o próximo passo','Feche a sessão e organize sua revisão.',10]];
function home(){const d=day(),l=LESSONS.find(x=>x.id===d.lesson);return head('SEU PLANO, NO SEU RITMO','Um bom dia para começar.','Você não precisa saber tudo hoje. Precisa dar o próximo passo.','ROTINA DE 2 HORAS')+`<section class="hero"><div><div class="eyebrow">${state.completed.length?'CONTINUE CONSTRUINDO SUA BASE':'SEU PRIMEIRO CAPÍTULO'}</div><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)} Uma introdução com exemplos e questões comentadas para tirar os conceitos do papel.</p><a class="btn light" href="#aula/${l.id}">Começar minha aula <span>→</span></a><span class="pill">◷ ${l.minutes} min de leitura e atividade · nível inicial</span></div><div class="hero-art" aria-hidden="true"><div class="orbit"><div class="code-symbol">&lt;/&gt;</div></div></div></section>`+stats()+`<div class="columns"><section><div class="section-title"><h2>Seu roteiro de hoje</h2><span class="subtle">${d.checks.length} de 5 etapas</span></div><div class="card">${DAILY.map((s,i)=>`<div class="session-row"><span class="step ${d.checks.includes(i)?'done':''}">${d.checks.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><div class="grow"><h3>${s[0]}</h3><p>${s[1]}</p></div><span class="time">${s[2]} min</span><label title="Marcar etapa concluída"><input type="checkbox" data-step="${i}" aria-label="Concluir ${s[0]}" ${d.checks.includes(i)?'checked':''}></label></div>`).join('')}</div><div class="section-title"><h2>Pequenos passos, durante a semana</h2></div><div class="week-strip">${['Seg','Ter','Qua','Qui','Sex','Sáb'].map((x,i)=>`<div class="week-day ${(new Date().getDay()+6)%7===i?'active':''}">${x}<br>2 horas</div>`).join('')}</div><p class="subtle">Domingo livre. Se perder um dia, retome a sequência; não acumule uma dívida de estudo.</p></section><aside><div class="section-title"><h2>O próximo passo é simples</h2></div><div class="card tip"><div class="icon">✧</div><h3>Entender vem antes de acelerar.</h3><p>Leia um conceito, tente explicá-lo sem consultar e só então resolva questões. Cada erro mostra o que revisar.</p><a href="#questoes?area=${encodeURIComponent(l.area)}" class="inline-link">Praticar este assunto →</a></div><div class="card"><h3>Seu caderno TEC está por aqui</h3><p class="subtle">Índice analisado em 9 áreas. Acesso externo e treino autoral ficam identificados.</p><a class="btn secondary full" href="#tec">Abrir área TEC ↗</a></div>${timerHTML()}</aside></div>`;}
function trail(){return head('APRENDER DESDE O INÍCIO','Sua trilha de aprendizado.','Oito aulas de fundamentos para começar. O índice completo orienta as próximas expansões.')+`<div class="notice">Introduções disponíveis, não um curso completo do edital. Avance no seu ritmo; marcar leitura não significa domínio do assunto.</div><div class="lesson-grid">${LESSONS.map((l,i)=>`<article class="card lesson-card"><div class="lesson-meta"><span class="tag">${String(i+1).padStart(2,'0')} · ${esc(l.area)}</span><small>${state.completed.includes(l.id)?'✓ Lida':l.minutes+' min'}</small></div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p><a class="btn secondary" href="#aula/${l.id}">${state.completed.includes(l.id)?'Revisitar aula':'Abrir aula'} →</a></article>`).join('')}</div><div class="section-title" style="margin-top:32px"><h2>Mapa do programa de referência</h2><a href="programa-base.md" download>Baixar programa integral ↓</a></div><p class="subtle">Resumo de navegação. Use o documento integral para controlar todos os subitens e as diferenças por cargo.</p>${PROGRAM.map(p=>`<details class="index-group"><summary>${esc(p[0])} <small>${esc(p[1])}</small></summary><p>${esc(p[2])}</p></details>`).join('')}`;}
function lesson(id){const l=LESSONS.find(x=>x.id===id);if(!l)return notFound();const i=LESSONS.indexOf(l);return `<a href="#trilha" class="back">← Voltar para a trilha</a>`+head(`AULA ${String(i+1).padStart(2,'0')} · ${esc(l.area)}`,esc(l.title),`${l.minutes} min sugeridos · fundamentos para iniciantes`)+`<article class="card lesson-body">${l.body}<h3>Fonte para aprofundar</h3><p>${sourceLink(l.source)}</p><p class="subtle">Texto introdutório autoral. A atividade é para raciocinar no papel; esta versão não executa código.</p><div class="answer-actions"><button class="btn" id="complete" data-lesson="${l.id}">${state.completed.includes(l.id)?'✓ Aula marcada como lida':'Marcar aula como lida'}</button><a class="btn secondary" href="#questoes?area=${encodeURIComponent(l.area)}">Praticar este assunto →</a></div></article>`;}
let answer=null,position=0,currentList=[],timer=null,timerEnd=0,remaining=25*60;
function readFilters(){const s=location.hash.split('?')[1]||'';return new URLSearchParams(s);}
function filterList(p){return QUESTIONS.filter(q=>(!p.get('area')||q.area===p.get('area'))&&(!p.get('level')||q.level===p.get('level'))&&(!p.get('cargo')||q.cargos.includes(p.get('cargo')))&&(!p.get('search')||`${q.text} ${q.id}`.toLowerCase().includes(p.get('search').toLowerCase()))&&(!p.get('lesson')||q.lesson===p.get('lesson'))&&(!p.get('id')||q.id===p.get('id'))&&(!p.get('due')||due().some(x=>x.id===q.id))&&(!p.get('status')||(p.get('status')==='novas'?!last(q.id):p.get('status')==='erros'?last(q.id)&&!last(q.id).correct:last(q.id)?.guess)));}
const options=(values,selected,all)=>`<option value="">${all}</option>`+values.map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
function questions(){const p=readFilters();currentList=filterList(p);position=Math.min(position,Math.max(0,currentList.length-1));const q=currentList[position];return head('PRATICAR E COMPREENDER','Uma questão. Cinco aprendizados.','Responda e veja a análise de todas as alternativas, com indicação da fonte.')+`<div class="notice">${QUESTIONS.length} questões autorais de fundamentos, alinhadas a tópicos do programa. Não são questões oficiais FCC/TEC, nem previsão de prova. Comentários preparados previamente; não há tutor de IA em tempo real nesta versão.</div><form id="filters" class="filters"><label>Disciplina<select name="area">${options([...new Set(QUESTIONS.map(q=>q.area))],p.get('area'),'Todas as disciplinas')}</select></label><label>Nível<select name="level">${options(['Inicial','Fundamento'],p.get('level'),'Todos os níveis')}</select></label><label>Cargo<select name="cargo">${options(['Analista','Técnico'],p.get('cargo'),'Ambos')}</select></label><label>Seu histórico<select name="status">${optionsStatus(p.get('status'))}</select></label><label>Buscar no enunciado<input type="search" name="search" value="${esc(p.get('search')||'')}" placeholder="Termo ou código"></label><button class="btn" type="submit">Filtrar</button><a href="#questoes" class="inline-link">Limpar</a></form>${p.get('due')?'<div class="notice">Mostrando revisões vencidas. <a href="#questoes">Ver todas</a></div>':''}<div class="section-title"><span class="subtle">${currentList.length} questão(ões) neste filtro ${q?'· '+(position+1)+' de '+currentList.length:''}</span></div><div id="question-content">${q?questionCard(q):'<div class="empty">Nenhuma questão neste filtro. <a href="#questoes">Limpar filtros</a> e tentar outro assunto.</div>'}</div>`;}
function optionsStatus(s){return `<option value="">Todas as situações</option><option value="novas" ${s==='novas'?'selected':''}>Ainda não respondidas</option><option value="erros" ${s==='erros'?'selected':''}>Última resposta errada</option><option value="palpites" ${s==='palpites'?'selected':''}>Último acerto ou erro com palpite</option>`;}
function questionCard(q){return `<article class="card question-card"><div class="question-head"><span class="tag">${q.id} · ${esc(q.area)} · ${q.level}</span><small>Autoral · ${q.cargos.join(' e ')} · 2026</small></div><h2>${esc(q.text)}</h2><form id="answer-form"><fieldset style="border:0;padding:0;margin:0"><legend class="subtle">Escolha uma alternativa</legend>${q.options.map((o,i)=>`<label class="choice"><input type="radio" name="choice" value="${i}" required><b>${'ABCDE'[i]}</b><span>${esc(o)}</span></label>`).join('')}</fieldset><label class="checkline"><input type="checkbox" name="guess">Marquei com dúvida ou por palpite</label><div class="answer-actions"><button class="btn" type="submit">Responder e analisar →</button><span><button type="button" class="btn secondary" id="prev" ${position===0?'disabled':''}>←</button> <button type="button" class="btn secondary" id="next" ${position===currentList.length-1?'disabled':''}>Próxima →</button></span></div></form><div id="feedback" aria-live="polite"></div></article>`;}
function showFeedback(q,a){$('#feedback').innerHTML=`<section class="feedback"><h3 class="${a.correct?'success':'failure'}">${a.correct?'✓ Resposta correta':'Vamos entender o erro'} · gabarito ${'ABCDE'[q.correct]}</h3><p class="subtle">${a.guess?'Sua dúvida ficou registrada para revisão. ':''}${a.correct&&!a.guess?'Revisão sugerida em 7 dias.':'Revisão sugerida a partir de amanhã.'} Sua próxima tentativa fica disponível ao reabrir a questão.</p><h4>Análise alternativa por alternativa</h4>${q.explanations.map((e,i)=>`<div class="explain ${i===q.correct?'correct':''}"><b>${'ABCDE'[i]} · ${i===q.correct?'Correta':'Incorreta'}</b><p>${esc(e)}</p></div>`).join('')}<p class="subtle">Referência de estudo: ${sourceLink(q.source)}</p><a href="#aula/${q.lesson}" class="btn secondary">Revisar a aula deste assunto</a><h4>Seu caderno de erros</h4><label class="subtle" for="note">O que confundiu você? Escreva a distinção que vai lembrar.</label><textarea class="note-input" id="note" maxlength="5000" placeholder="Ex.: confundi autenticação com autorização.">${esc(state.notes[q.id]||'')}</textarea><button class="btn secondary" id="save-note">Salvar anotação</button><p class="subtle">O comentário acima já está preparado. Para dúvidas novas, anote aqui e traga a questão para nossa conversa.</p></section>`;
 $$('.choice').forEach((el,i)=>{if(i===q.correct)el.classList.add('correct');else if(i===a.selected)el.classList.add('wrong');});$('#save-note').onclick=()=>{state.notes[q.id]=$('#note').value;if(save())toast('Anotação salva neste navegador.');};}
function review(){const items=due(),errors=QUESTIONS.filter(q=>last(q.id)&&(!last(q.id).correct||last(q.id).guess));return head('RECORDAR PARA RETER','Suas revisões.','Erros e palpites voltam após 1 dia; acertos seguros, após 7 dias.')+`<div class="notice">Intervalos iniciais para organizar o estudo. O sistema usa a última resposta de cada questão e não estima domínio ou probabilidade de aprovação.</div>${items.length?`<div class="card"><h2>${items.length} revisões disponíveis</h2><a class="btn" href="#questoes?due=1">Começar revisão →</a></div>`:'<div class="empty">Nenhuma revisão vencida agora. Após responder, seus itens aparecerão aqui na data sugerida.</div>'}<h2 style="margin-top:30px">Erros e dúvidas para acompanhar</h2>${errors.length?errors.map(q=>`<div class="card"><div class="stack"><span class="tag">${q.id} · ${esc(q.area)}</span><a href="#questoes?id=${q.id}">Revisitar questão →</a></div><p>${esc(q.text.split('\n')[0])}</p><p class="subtle">${esc(state.notes[q.id]||'Você ainda não escreveu uma anotação para esta questão.')}</p></div>`).join(''):'<p class="muted">Quando houver uma resposta errada ou marcada com dúvida, ela aparecerá aqui.</p>'}`;}
function tec(){return head('SEU BANCO EXTERNO','Caderno TEC, no seu fluxo.','Referência: Especifico TI · Q7ByxA · índice consultado em 18/10/2026.')+`<div class="notice amber">O acesso depende da sua conta e das permissões do TEC. A incorporação não transfere respostas, estatísticas ou comentários para a Trilha TI. O índice abaixo é um mapeamento dos grupos observados, não uma importação do banco.</div><div class="card"><div class="stack"><a class="btn" href="https://www.tecconcursos.com.br/caderno/Q7ByxA" target="_blank" rel="noopener noreferrer">Abrir caderno no TEC ↗</a><button class="btn secondary" id="load-tec">Tentar exibir aqui</button></div><p class="subtle">Se o quadro pedir login, ficar vazio ou não permitir acesso, use o link acima. Não informe credenciais à Trilha TI.</p><div id="tec-host"></div></div><div class="columns"><section><div class="section-title"><h2>Índice analisado · 9 áreas</h2></div>${TEC_INDEX.map((x,i)=>`<details class="index-group"><summary>${String(i+1).padStart(2,'0')} · ${esc(x.name)}</summary><ul>${x.groups.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p class="notice amber">${esc(x.extras)}</p>${x.focus?`<a href="#questoes?area=${encodeURIComponent(x.focus)}">Treinar fundamentos autorais relacionados →</a>`:'<p class="subtle">Aulas e questões específicas deste eixo ainda serão ampliadas.</p>'}</details>`).join('')}</section><aside><div class="card"><h2>Registrar uma sessão TEC</h2><p class="subtle">Registro manual e separado. Não precisamos copiar enunciados ou comentários para acompanhar seu esforço.</p><form id="tec-log"><label class="checkline" for="tec-topic">Assunto estudado</label><input class="full" id="tec-topic" type="text" required maxlength="160" placeholder="Ex.: SQL — consultas"><label class="checkline" for="tec-total">Questões respondidas</label><input class="full" id="tec-total" type="number" min="1" max="1000" required><label class="checkline" for="tec-correct">Acertos</label><input class="full" id="tec-correct" type="number" min="0" max="1000" required><button class="btn full" style="margin-top:16px">Salvar registro manual</button></form></div><div class="card tip"><h3>O filtro não define o edital.</h3><p>O caderno inclui versões antigas e assuntos adicionais. Comece pelos fundamentos e confira o recorte do documento-base antes de ampliar.</p><a href="programa-base.md" download class="inline-link">Baixar programa-base ↓</a></div></aside></div>`;}
function progress(){const rows=[...new Set(QUESTIONS.map(q=>q.area))].map(area=>{const qs=QUESTIONS.filter(q=>q.area===area),done=qs.filter(q=>last(q.id)),ok=done.filter(q=>last(q.id).correct&&!last(q.id).guess);return `<tr><td>${esc(area)}</td><td>${done.length}/${qs.length}</td><td>${ok.length}</td><td>${done.length?Math.round(ok.length/done.length*100)+'%':'—'}</td></tr>`;});return head('SUA JORNADA EM DADOS','Progresso que ajuda a decidir.','Observe os erros e os assuntos que ainda não começou. Esta amostra não prevê sua nota.')+stats()+`<div class="card"><h2>Questões autorais por disciplina</h2><div style="overflow:auto"><table class="progress-table"><thead><tr><th>Disciplina</th><th>Questões únicas</th><th>Últimos acertos seguros</th><th>Taxa</th></tr></thead><tbody>${rows.join('')}</tbody></table></div><p class="subtle">A taxa considera a última tentativa, e exclui acertos marcados como palpite do numerador. Tentativas totais: ${state.attempts.length}. Refazer o mesmo item pode medir memória.</p></div><div class="card"><h2>Sessões TEC registradas manualmente</h2>${state.tec.length?state.tec.slice(-15).reverse().map(x=>`<div class="mini-row"><span>${esc(x.topic)} · ${new Date(x.time).toLocaleDateString('pt-BR')}</span><span>${x.correct}/${x.total}</span></div>`).join(''):'<p class="subtle">Nenhum registro ainda. Anote sua sessão pela área Caderno TEC.</p>'}<p class="subtle">${state.tec.length} sessão(ões) registradas. Estes dados são autodeclarados e não entram na taxa do banco autoral.</p></div><div class="card"><h2>Seu progresso pertence a você</h2><p class="subtle">Salvo somente neste navegador. Não há sincronização entre celular e computador nesta versão. Exporte antes de mudar de dispositivo ou limpar dados.</p><div class="stack"><button class="btn" id="export">Exportar meu progresso ↓</button><label class="btn secondary" for="backup">Restaurar backup<input type="file" id="backup" accept="application/json,.json" hidden></label></div><p class="subtle">A restauração validada substitui o progresso deste navegador, com confirmação. Só são aceitos backups da Trilha TI; não importa bancos de questões externos.</p><p id="backup-status" role="status"></p></div>`;}
function about(){return head('TRANSPARÊNCIA E CONTINUIDADE','Uma base para estudar com clareza.','Primeira versão · fundamentos disponíveis · expansão por etapas.')+`<div class="card prose"><h2>O que já funciona</h2><ul><li>Rotina sugerida de 120 minutos e timer de foco.</li><li>8 aulas introdutórias e 24 questões autorais com cinco alternativas comentadas.</li><li>Filtros por disciplina, dificuldade, cargo, situação e texto.</li><li>Registro de dúvidas, revisões sugeridas, histórico local e backup.</li><li>Índice analisado do caderno TEC e tentativa de incorporação, com abertura externa alternativa.</li></ul><h2>O que ainda precisa ser ampliado</h2><p>O material disponível não cobre integralmente o edital. Sistemas operacionais, Direito, gerais, Inglês, redação e aprofundamentos técnicos têm programa mapeado, mas ainda não contam com aulas e banco próprios. As questões são iniciais e não equivalem à complexidade completa de Analista.</p><h2>Origem e tribunal</h2><p>Usamos o edital TRT8/FCC enviado pelo usuário. Analista é a prioridade; Técnico aproveita o núcleo comum, respeitando recortes próprios. Para Mato Grosso, a referência territorial é TRT23; TRT1 atende Rio de Janeiro. O destino definitivo e as normas locais continuam pendentes de confirmação.</p><h2>Questões e comentários</h2><p>Os exercícios são autorais de preparação, não provas oficiais nem cópias do TEC. As explicações são previamente redigidas, sem um modelo de IA conectado em tempo real. A seleção dos tópicos segue fundamentos do programa, sem previsão de incidência ou promessa de aprovação.</p><h2>Integração com o TEC</h2><p>O caderno foi consultado na interface autenticada, com autorização do usuário, para mapear grupos do índice. Os filtros internos de criação do caderno não foram auditados integralmente. Não foram importados enunciados, gabaritos, comentários ou estatísticas.</p><p>Um iframe mostra o site externo quando ele permite; o isolamento entre origens impede leitura arbitrária dos dados internos. Login, plano e políticas de cookies podem impedir o quadro. Uma integração completa requer mecanismo documentado e autorização do fornecedor; nenhum foi validado nesta etapa.</p><p><a href="https://www.tecconcursos.com.br/termos-de-uso" target="_blank" rel="noopener noreferrer">Termos do TEC ↗</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Same-origin_policy" target="_blank" rel="noopener noreferrer">Isolamento entre origens — MDN ↗</a></p><h2>Arquivos do projeto</h2><p><a href="programa-base.md" download>Programa-base integral</a> · <a href="plano-estudos.md" download>Plano inicial de estudos</a> · <a href="analise-tec.md" download>Análise de integração e índice TEC</a></p><h2>Fontes de aprofundamento</h2><ul>${Object.keys(SOURCES).map(k=>`<li>${sourceLink(k)}</li>`).join('')}</ul><h2>Dados e privacidade</h2><p>O histórico usa armazenamento local e não é enviado a um servidor da aplicação. O quadro TEC só carrega quando solicitado; o acesso ao TEC segue suas próprias políticas. Fontes tipográficas podem ser carregadas do Google Fonts. Backups ficam no dispositivo escolhido.</p></div>`;}
function timerHTML(){return `<div class="card timer-card"><div class="section-title"><h3>Um bloco de foco</h3><span class="tag">25 MIN</span></div><div id="timer-display" class="timer">${timeString()}</div><p class="subtle">Timer de apoio. Não registra horas estudadas.</p><div class="stack"><button class="btn secondary" id="timer-toggle">${timer?'Pausar':'Iniciar'}</button><button class="inline-link" id="timer-reset">Reiniciar</button></div><p class="subtle">Ao trocar de aba, o tempo considera o relógio. Ao fechar a página, o timer é encerrado.</p></div>`;}
function timeString(){return `${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;}
function tick(){remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if($('#timer-display'))$('#timer-display').textContent=timeString();if(!remaining){clearInterval(timer);timer=null;if($('#timer-toggle'))$('#timer-toggle').textContent='Iniciar';toast('Seu bloco de foco terminou. Faça uma pausa.');}}
function notFound(){return head('VAMOS RETOMAR','Página não encontrada.','Escolha uma área pelo menu.')+'<a href="#inicio" class="btn">Voltar ao início</a>';}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bind(){
 $$('[data-step]').forEach(c=>c.onchange=()=>{const d=day(),v=Number(c.dataset.step);d.checks=c.checked?[...new Set([...d.checks,v])]:d.checks.filter(x=>x!==v);save();render(false);});
 if($('#complete'))$('#complete').onclick=()=>{const id=$('#complete').dataset.lesson;if(!state.completed.includes(id))state.completed.push(id);if(save()){toast('Leitura registrada. Pratique para verificar o que entendeu.');render(false);}};
 if($('#filters'))$('#filters').onsubmit=e=>{e.preventDefault();const p=new URLSearchParams();new FormData(e.target).forEach((v,k)=>{if(v)p.set(k,v);});position=0;nav('questoes'+(p.size?'?'+p.toString():''));};
 if($('#answer-form'))$('#answer-form').onsubmit=e=>{e.preventDefault();if(answer)return;const q=currentList[position],fd=new FormData(e.target),selected=Number(fd.get('choice'));if(fd.get('choice')===null)return;answer={id:q.id,selected,correct:selected===q.correct,guess:fd.has('guess'),time:Date.now()};state.attempts.push(answer);save();e.target.querySelector('button[type=submit]').disabled=true;e.target.querySelectorAll('input').forEach(x=>x.disabled=true);showFeedback(q,answer);$('#review-count').textContent=due().length;};
 if($('#next'))$('#next').onclick=()=>{position++;answer=null;render(false);};if($('#prev'))$('#prev').onclick=()=>{position--;answer=null;render(false);};
 if($('#load-tec'))$('#load-tec').onclick=()=>{$('#tec-host').innerHTML='<p class="subtle">Conteúdo externo fornecido pelo TEC. Se o quadro não carregar, use o link acima.</p><iframe class="tec-frame" title="Caderno TEC Q7ByxA — conteúdo externo" src="https://www.tecconcursos.com.br/caderno/Q7ByxA" sandbox="allow-scripts allow-forms allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-downloads" referrerpolicy="strict-origin-when-cross-origin"></iframe>';$('#load-tec').disabled=true;};
 if($('#tec-log'))$('#tec-log').onsubmit=e=>{e.preventDefault();const total=Number($('#tec-total').value),correct=Number($('#tec-correct').value),topic=$('#tec-topic').value.trim();if(!topic||!Number.isInteger(total)||!Number.isInteger(correct)||total<1||total>1000||correct<0||correct>total){toast('Confira o assunto e os números: acertos não podem superar o total.');return;}state.tec.push({topic,total,correct,time:Date.now()});if(save()){e.target.reset();toast('Sessão TEC registrada manualmente.');}};
 if($('#export'))$('#export').onclick=()=>download(JSON.stringify(state,null,2),'trilha-ti-progresso-'+dateKey()+'.json','application/json');
 if($('#backup'))$('#backup').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8*1024*1024)throw Error('Arquivo muito grande.');const next=validate(JSON.parse(await f.text()));if(!confirm('Restaurar este backup e substituir o progresso atual? Exporte primeiro se quiser guardar a versão atual.'))return;state=next;if(save()){render(false);toast('Backup restaurado.');}}catch(err){$('#backup-status').textContent='Não foi possível restaurar: '+err.message;}e.target.value='';};
 if($('#timer-toggle'))$('#timer-toggle').onclick=()=>{if(timer){tick();clearInterval(timer);timer=null;}else{if(!remaining)remaining=1500;timerEnd=Date.now()+remaining*1000;timer=setInterval(tick,1000);}$('#timer-toggle').textContent=timer?'Pausar':'Iniciar';};
 if($('#timer-reset'))$('#timer-reset').onclick=()=>{clearInterval(timer);timer=null;remaining=1500;$('#timer-display').textContent=timeString();$('#timer-toggle').textContent='Iniciar';};
}
function render(scroll=true){const hash=location.hash.slice(1)||'inicio',path=hash.split('?')[0],tab=path.startsWith('aula/')?'trilha':path;$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===tab);if(a.dataset.nav===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#review-count').textContent=due().length;$('#breadcrumb').textContent=({inicio:'Seu espaço de estudos',trilha:'Aprendizado / Sua trilha',questoes:'Prática / Banco autoral',revisoes:'Aprendizado / Revisões',tec:'Integrações / Caderno TEC',progresso:'Seu estudo / Progresso',sobre:'Sobre / Fontes e limites'})[tab]||'Aprendizado / Aula';answer=null;const html=path==='inicio'?home():path==='trilha'?trail():path.startsWith('aula/')?lesson(path.slice(5)):path==='questoes'?questions():path==='revisoes'?review():path==='tec'?tec():path==='progresso'?progress():path==='sobre'?about():notFound();$('#main').innerHTML=(!storageOK?'<div class="notice amber">Armazenamento indisponível ou dados inválidos. As alterações desta sessão podem não persistir. Exporte o progresso antes de fechar.</div>':'')+html;bind();if(scroll)window.scrollTo(0,0);}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('#main').focus();});
window.addEventListener('hashchange',()=>{position=0;render();});render();
